// Draw a cool-toned fractal spiral
ctx.fillStyle = '#0a0a2a';
ctx.fillRect(0, 0, W, H);

const drawSpiral = (x, y, len, dir, depth) => {
    if (depth > 0) {
        // Pick cool tones
        const tone = ['#0a0a2a', '#1a1a4a', '#2a2a6a', '#3a3a8a', '#4a4aa0'];
        ctx.fillStyle = tone[depth % tone.length];

        // Draw segment
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + len * Math.cos(dir), y - len * Math.sin(dir));
        ctx.fill();

        // Recursive calls for four arms
        drawSpiral(x + len * Math.cos(dir), y - len * Math.sin(dir),
                   len * 0.7, dir + Math.PI/2, depth + 1);
        drawSpiral(x + len * Math.cos(dir), y - len * Math.sin(dir),
                   len * 0.7, dir - Math.PI/2, depth + 1);
        drawSpiral(x - len * Math.sin(dir), y + len * Math.cos(dir),
                   len * 0.7, dir - Math.PI/2, depth + 1);
        drawSpiral(x - len * Math.sin(dir), y + len * Math.cos(dir),
                   len * 0.7, dir + Math.PI/2, depth + 1);
    }
};

