// Shell (spiral pattern)
ctx.fillStyle = '#8B4513';
for (let i = 0; i < 15; i++) {
    const radius = 15 + i * 8;
    const angle = i * 0.3;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    ctx.beginPath();
    ctx.arc(x, y, 8, 0, Math.PI * 2);
    ctx.fill();
}

// Shell details (small circles)
ctx.fillStyle = '#654321';
for (let i = 0; i < 10; i++) {
    const radius = 12 + i * 4;
    const angle = i * 0.4;
    const x = 200 + Math.cos(angle) * radius;
    const y = 250 + Math.sin(angle) * radius;
    ctx.beginPath();
    ctx.arc(x, y, 3, 0, Math.PI * 2);
    ctx.fill();
}

// Shell spiral lines
ctx.strokeStyle = '#5D2906';
ctx.lineWidth = 1;
for (let i = 0; i < 10; i++) {
    const radius = 18 + i * 7;
    const angle = i * 0.5;
    const x1 = 200 + Math.cos(angle) * radius;
    const y1 = 250 + Math.sin(angle) * radius;
    const angle2 = (i + 0.5) * 0.5;
    const x2 = 200 + Math.cos(angle2) * (radius + 3);
    const y2 = 250 + Math.sin(angle2) * (radius + 3);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

// Snail antennae
