// Snail legs
ctx.strokeStyle = '#000';
ctx.lineWidth = 3;
for (let i = 0; i < 3; i++) {
    const angle = i * Math.PI / 3;
    const x1 = 200 + Math.cos(angle) * 20;
    const y1 = 250 + Math.sin(angle) * 20;
    const x2 = 200 + Math.cos(angle) * 30;
    const y2 = 250 + Math.sin(angle) * 30;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

